create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,plan text not null default 'free' check(plan in ('free','seedling','grower','pro')),diagnoses_used integer not null default 0,created_at timestamptz not null default now());
create table if not exists public.plants(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,species text,notes text,created_at timestamptz not null default now());
create table if not exists public.diagnoses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,plant_id uuid references public.plants(id) on delete set null,plant_name text,condition text,severity text,confidence numeric,symptoms jsonb not null default '[]',likely_causes jsonb not null default '[]',treatment jsonb not null default '[]',prevention jsonb not null default '[]',care_plan jsonb not null default '[]',created_at timestamptz not null default now());
create table if not exists public.payments(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,provider text not null,provider_order_id text unique,provider_payment_id text,plan text not null,amount integer not null,status text not null,created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.plants enable row level security;alter table public.diagnoses enable row level security;alter table public.payments enable row level security;
create policy "profiles own" on public.profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy "plants own" on public.plants for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "diagnoses own" on public.diagnoses for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "payments own" on public.payments for select using(auth.uid()=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,new.raw_user_meta_data->>'display_name'); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into storage.buckets(id,name,public) values('plant-images','plant-images',false) on conflict(id) do nothing;